let menuIcon=document.querySelector("#menu-icon"),navbar=document.querySelector(".navbar");menuIcon.onclick=()=>{menuIcon.classList.toggle("bx-x"),navbar.classList.toggle("active")};let sections=document.querySelectorAll("section"),navLinks=document.querySelectorAll("header nav a");window.onscroll=()=>{sections.forEach(e=>{let t=window.scrollY,o=e.offsetTop-150,r=e.offsetHeight,s=e.getAttribute("id");t>=o&&t<o+r&&navLinks.forEach(e=>{e.classList.remove("active"),document.querySelector("header nav a[href*="+s+"]").classList.add("active")})});document.querySelector("header").classList.toggle("sticky",window.scrollY>100),menuIcon.classList.remove("bx-x"),navbar.classList.remove("active")};const sr=ScrollReveal({reset:!0,distance:"70px",duration:2e3,delay:200});sr.reveal(".home-content",{origin:"top"}),sr.reveal(".skills-box",{origin:"bottom",interval:150}),sr.reveal(".home-img, .project-box, .contact-box",{origin:"bottom"}),sr.reveal(".home-content h1, .about-img",{origin:"left"}),sr.reveal(".home-content p, .about-content",{origin:"right"});const typed=new Typed("#multitext",{strings:["Web Developer","Student","Tech enthusiast"],typeSpeed:100,backSpeed:100,backDelay:1e3,loop:!0});